sealed partial class Main {
 void Login(){if(operation!=null){SetStatus("Cancel loading before changing account.");return;}using var dialog=new Form{Text="Connect IPTV account",Size=new(610,430)};Ui.Dark(dialog);var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new(22)};grid.ColumnStyles.Add(new(SizeType.Absolute,145));grid.ColumnStyles.Add(new(SizeType.Percent,100));dialog.Controls.Add(grid);void Row(string label,Control c){grid.Controls.Add(Ui.Label(label));grid.Controls.Add(c);}var mode=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};mode.Items.AddRange(new object[]{"Xtream Codes","M3U"});mode.SelectedItem=saved.Mode;var server=new TextBox{Text=saved.Server,Dock=DockStyle.Fill};var user=new TextBox{Text=saved.User,Dock=DockStyle.Fill};var secret=new TextBox{Text=SettingsStore.Secret(saved),UseSystemPasswordChar=true,Dock=DockStyle.Fill};Row("Login type",mode);Row("Server / M3U URL",server);Row("Username",user);Row("Password",secret);Row("Local playlist",Ui.Button("Choose M3U file",()=>{using var picker=new OpenFileDialog{Filter="M3U playlist|*.m3u;*.m3u8|All files|*.*"};if(picker.ShowDialog(dialog)==DialogResult.OK){mode.SelectedItem="M3U";server.Text=picker.FileName;}}));var save=new CheckBox{Text="Remember account on this Windows user",Checked=remember,AutoSize=true};Row("Privacy",save);bool connect=false;Row("",Ui.Button("Connect",()=>{saved.Mode=mode.Text;saved.Server=server.Text.Trim();saved.User=user.Text.Trim();saved.Secret=SettingsStore.Protect(secret.Text);remember=save.Checked;if(remember)TrySave();connect=true;dialog.Close();}));Row("",Ui.Button("Use M3U fallback",()=>{if(saved.Mode!="Xtream Codes")return;dialog.Close();_ = Connect(true);}));dialog.ShowDialog(this);if(connect)_ = Connect();}
 void Settings(){using var dialog=new Form{Text="Settings",Size=new(650,400)};Ui.Dark(dialog);var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new(20)};grid.ColumnStyles.Add(new(SizeType.Absolute,165));grid.ColumnStyles.Add(new(SizeType.Percent,100));dialog.Controls.Add(grid);var epg=new TextBox{Text=saved.EpgUrl,Dock=DockStyle.Fill};var folder=new TextBox{Text=saved.DownloadFolder,Dock=DockStyle.Fill};var volume=new NumericUpDown{Minimum=0,Maximum=100,Value=saved.Volume};grid.Controls.Add(Ui.Label("XMLTV EPG URL/file"));grid.Controls.Add(epg);grid.Controls.Add(Ui.Label("Downloads folder"));grid.Controls.Add(folder);grid.Controls.Add(Ui.Label(""));grid.Controls.Add(Ui.Button("Choose folder",()=>{using var picker=new FolderBrowserDialog{SelectedPath=folder.Text};if(picker.ShowDialog(dialog)==DialogResult.OK)folder.Text=picker.SelectedPath;}));grid.Controls.Add(Ui.Label("Default volume"));grid.Controls.Add(volume);grid.Controls.Add(Ui.Label(""));grid.Controls.Add(Ui.Button("Save",()=>{saved.EpgUrl=epg.Text.Trim();saved.DownloadFolder=folder.Text.Trim();if(saved.DownloadFolder.Length==0)saved.DownloadFolder=new Saved().DownloadFolder;saved.Volume=(int)volume.Value;TrySave();dialog.Close();}));grid.Controls.Add(Ui.Label(""));grid.Controls.Add(Ui.Button("Cancel loading",()=>{operation?.Cancel();dialog.Close();}));grid.Controls.Add(Ui.Label(""));grid.Controls.Add(Ui.Button("Preview sample library",()=>{new Main(true).Show(this);dialog.Close();}));dialog.ShowDialog(this);}
