sealed class EpisodesWindow:Form {
 readonly Channel series;readonly Func<CancellationToken,Task<List<Channel>>> fetch;readonly Action<Channel> play,download,favorite;readonly CancellationTokenSource lifetime=new();readonly ComboBox seasons=new(){Dock=DockStyle.Top,DropDownStyle=ComboBoxStyle.DropDownList};readonly ListBox list=new(){Dock=DockStyle.Fill,DisplayMember="Name"};readonly Label state=Ui.Label("Loading episodes…",32);List<Channel> episodes=new();
 public EpisodesWindow(Channel media,Func<CancellationToken,Task<List<Channel>>> load,Action<Channel> start,Action<Channel> save,Action<Channel> star){series=media;fetch=load;play=start;download=save;favorite=star;Ui.Dark(this);Text=series.Name+" — Seasons & Episodes";Size=new(720,620);list.BackColor=Ui.Surface;list.ForeColor=Ui.Text;Controls.Add(list);Controls.Add(seasons);Controls.Add(state);var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50};actions.Controls.Add(Ui.Button("Play episode",Start));actions.Controls.Add(Ui.Button("Download episode",()=>{if(list.SelectedItem is Channel c)download(c);}));actions.Controls.Add(Ui.Button("★ Favorite",()=>{if(list.SelectedItem is Channel c)favorite(c);}));Controls.Add(actions);seasons.SelectedIndexChanged+=(_,_)=>{list.Items.Clear();foreach(var ep in episodes.Where(c=>"Season "+c.Season==seasons.Text))list.Items.Add(ep);};list.DoubleClick+=(_,_)=>Start();FormClosed+=(_,_)=>lifetime.Cancel();}
 void Start(){if(list.SelectedItem is Channel c){play(c);Close();}}
 public async Task LoadEpisodes(){try{episodes=await fetch(lifetime.Token);if(IsDisposed)return;foreach(var season in episodes.Select(c=>c.Season).Distinct().OrderBy(s=>int.TryParse(s,out int n)?n:int.MaxValue))seasons.Items.Add("Season "+season);if(seasons.Items.Count>0)seasons.SelectedIndex=0;state.Text=episodes.Count+" episodes";}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed)state.Text=ProviderTransport.ErrorText(e);}}
}
sealed class GuideWindow:Form {
 readonly ProviderService provider;readonly Action<Channel> play;readonly bool catchup;readonly List<Channel> channels;Channel channel;readonly ListView rows=new(){Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,HideSelection=false};readonly Label state=Ui.Label("Loading guide…",48);readonly TextBox description=new(){Dock=DockStyle.Bottom,Height=105,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};CancellationTokenSource? loading;List<EpgProgramme> programmes=new();
 public GuideWindow(ProviderService service,List<Channel> available,Channel selected,bool archive,Action<Channel> start){provider=service;channels=available;channel=selected;catchup=archive;play=start;Ui.Dark(this);Text=archive?"Catch-up TV":"Electronic Programme Guide";Size=new(920,650);rows.BackColor=Ui.Surface;rows.ForeColor=Ui.Text;rows.Columns.Add("Start",155);rows.Columns.Add("End",95);rows.Columns.Add("Programme",470);Controls.Add(rows);Controls.Add(state);Controls.Add(description);var actions=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48};actions.Controls.Add(Ui.Button("Choose channel",()=>{using var picker=new ChannelPicker(channels);if(picker.ShowDialog(this)==DialogResult.OK&&picker.Selected!=null){channel=picker.Selected;_ = LoadGuide();}}));actions.Controls.Add(Ui.Button("Refresh guide",()=>_ = LoadGuide()));actions.Controls.Add(Ui.Button("Play live",()=>play(channel)));actions.Controls.Add(Ui.Button("Play archive",Archive));Controls.Add(actions);rows.SelectedIndexChanged+=(_,_)=>{if(rows.SelectedIndices.Count>0)description.Text=programmes[rows.SelectedIndices[0]].Description;};rows.DoubleClick+=(_,_)=>Archive();FormClosed+=(_,_)=>loading?.Cancel();}
 public async Task LoadGuide(){loading?.Cancel();var tokenSource=new CancellationTokenSource();loading=tokenSource;state.Text=channel.Name+" — loading schedule…";try{var data=await provider.Guide(channel,tokenSource.Token);if(IsDisposed||loading!=tokenSource)return;programmes=data.Where(p=>!catchup||p.Start<DateTimeOffset.UtcNow&&(channel.ArchiveDays<=0||p.Start>DateTimeOffset.UtcNow.AddDays(-channel.ArchiveDays))).ToList();rows.Items.Clear();foreach(var p in programmes)rows.Items.Add(new ListViewItem(new[]{p.Start.LocalDateTime.ToString("MMM dd HH:mm"),p.End.LocalDateTime.ToString("HH:mm"),p.Title}));state.Text=channel.Name+" — "+programmes.Count+" programmes"+(programmes.Count==0?". The provider supplied no matching schedule.":"");}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed&&loading==tokenSource)state.Text=ProviderTransport.ErrorText(e);}finally{tokenSource.Dispose();if(loading==tokenSource)loading=null;}}
 void Archive(){if(rows.SelectedIndices.Count==0)return;try{play(provider.Catchup(channel,programmes[rows.SelectedIndices[0]]));}catch(Exception e){state.Text=ProviderTransport.ErrorText(e);}}
}
sealed class TransfersWindow:Form {
 readonly TransferManager manager;readonly ListView list=new(){Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,HideSelection=false};readonly System.Windows.Forms.Timer timer=new(){Interval=600};
 public TransfersWindow(TransferManager transfers){manager=transfers;Ui.Dark(this);Text="Downloads & Live Recordings";Size=new(1030,520);list.BackColor=Ui.Surface;list.ForeColor=Ui.Text;foreach(var(name,width)in new[]{("Title",280),("Type",110),("State",100),("Progress",160),("Details",330)})list.Columns.Add(name,width);Controls.Add(list);var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50};actions.Controls.Add(Ui.Button("Stop selected",()=>{if(Selected() is{} job)job.Stop();}));actions.Controls.Add(Ui.Button("Open folder",()=>{if(Selected() is{} job){string folder=Path.GetDirectoryName(job.File)!;if(Directory.Exists(folder))System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(folder){UseShellExecute=true});}}));Controls.Add(actions);timer.Tick+=(_,_)=>RefreshJobs();timer.Start();RefreshJobs();FormClosed+=(_,_)=>timer.Dispose();}
 TransferJob? Selected()=>list.SelectedIndices.Count>0&&list.SelectedIndices[0]<manager.Jobs.Count?manager.Jobs[list.SelectedIndices[0]]:null;
 void RefreshJobs(){while(list.Items.Count<manager.Jobs.Count)list.Items.Add(new ListViewItem(new[]{"","","","",""}));for(int i=0;i<manager.Jobs.Count;i++){var job=manager.Jobs[i];var s=job.Status;string progress=s.Total>0?$"{100d*s.Bytes/s.Total:0}%  {s.Bytes/1048576d:0.0} MB":$"{s.Bytes/1048576d:0.0} MB";var values=new[]{job.Name,job.Type,s.State,progress,s.Detail};for(int c=0;c<values.Length;c++)list.Items[i].SubItems[c].Text=values[c];}}
}





